"""Publish a dedicated, mutable demo release using only Python's standard library."""

import hashlib
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path


def api(method, path, data=None, content_type="application/json"):
    url = path if path.startswith("https://") else "https://api.github.com" + path
    body = (
        json.dumps(data).encode()
        if content_type == "application/json" and data is not None
        else data
    )
    request = urllib.request.Request(
        url,
        data=body,
        method=method,
        headers={
            "Authorization": "Bearer " + os.environ["GH_TOKEN"],
            "Accept": "application/vnd.github+json",
            "Content-Type": content_type,
            "X-GitHub-Api-Version": "2022-11-28",
            "User-Agent": "nested-tmux2-demo-publisher",
        },
    )
    with urllib.request.urlopen(request, timeout=120) as response:
        payload = response.read()
        return json.loads(payload) if payload else None


def publish(directory):
    repo = os.environ["SOURCE_REPOSITORY"]
    commit = os.environ["SOURCE_SHA"]
    base = f"/repos/{repo}"
    files = {
        "demo.gif": "image/gif",
        "demo.mp4": "video/mp4",
        "demo.cast": "application/x-asciicast",
    }
    # Verify every artifact before modifying the release.
    payloads = {name: (directory / name).read_bytes() for name in files}
    if not all(payloads.values()):
        raise RuntimeError("empty demo artifact")
    payloads["SHA256SUMS"] = "".join(
        f"{hashlib.sha256(payload).hexdigest()}  {name}\n" for name, payload in payloads.items()
    ).encode()
    payloads["source-commit.txt"] = (commit + "\n").encode()
    files.update({"SHA256SUMS": "text/plain", "source-commit.txt": "text/plain"})
    metadata = {
        "tag_name": "demo",
        "target_commitish": commit,
        "name": "Terminal demo",
        "body": f"Generated by `nix build .#demo` from [{commit[:12]}](https://github.com/{repo}/commit/{commit}).\n\n"
        "The GIF is embedded in README.md. Download the MP4 or replay the asciinema recording.\n\n"
        "This dedicated demo release is refreshed after successful main-branch builds.",
        "prerelease": True,
        "make_latest": "false",
    }
    try:
        release = api("GET", base + "/releases/tags/demo")
    except urllib.error.HTTPError as exc:
        if exc.code != 404:
            raise
        release = api("POST", base + "/releases", metadata)
    else:
        # Only the dedicated demo tag moves; versioned releases remain immutable.
        api("PATCH", base + "/git/refs/tags/demo", {"sha": commit, "force": True})
        release = api("PATCH", base + f"/releases/{release['id']}", metadata)
    existing = {asset["name"]: asset["id"] for asset in release["assets"]}
    upload = release["upload_url"].split("{", 1)[0]
    for name, content_type in files.items():
        # Upload first, then replace the stable filename. A failed upload leaves
        # the previous README image intact rather than deleting it preemptively.
        pending = name + ".pending"
        if pending in existing:
            api("DELETE", base + f"/releases/assets/{existing[pending]}")
        asset = api(
            "POST",
            upload + "?" + urllib.parse.urlencode({"name": pending}),
            payloads[name],
            content_type,
        )
        if name in existing:
            api("DELETE", base + f"/releases/assets/{existing[name]}")
        api("PATCH", base + f"/releases/assets/{asset['id']}", {"name": name})
        print(f"Published {name} ({len(payloads[name])} bytes)")
    print(release["html_url"])


if __name__ == "__main__":
    publish(Path(sys.argv[1]))
